import os, re, json
root='c:/Users/linus/git/context-engine/.session/sessions'
ticket_root='c:/Users/linus/git/context-engine/.ticket/tickets'
pat=re.compile(r'\b[0-9a-f]{8}\b')
sessions=os.listdir(root)
sessions_scanned=0
sessions_with_hex8=0
token_sessions={}
sessions_with_target=set()
distinct_target_ids=set()
for s in sessions:
    sd=os.path.join(root,s)
    if not os.path.isdir(sd):
        continue
    sessions_scanned+=1
    found_tokens=set()
    for fn in os.listdir(sd):
        fp=os.path.join(sd,fn)
        # skip large files >5MB
        try:
            if os.path.getsize(fp)>5*1024*1024:
                continue
        except Exception:
            continue
        try:
            with open(fp,'r',encoding='utf-8') as f:
                txt=f.read()
        except Exception:
            continue
        for m in pat.findall(txt):
            found_tokens.add(m)
            token_sessions.setdefault(m,set()).add(s)
        # check for target_tickets key in any JSON
        if 'target_tickets' in txt:
            try:
                j=json.loads(txt)
                tt=j.get('target_tickets')
                if tt:
                    # if list, add
                    if isinstance(tt,list) and len(tt)>0:
                        sessions_with_target.add(s)
                        for t in tt:
                            distinct_target_ids.add(t if isinstance(t,str) else str(t))
            except Exception:
                pass
    if found_tokens:
        sessions_with_hex8+=1
# compute top tokens
token_counts=[(t,len(ss)) for t,ss in token_sessions.items()]
token_counts.sort(key=lambda x: x[1], reverse=True)
top_tokens=token_counts[:10]
# top5 resolve
resolutions=[]
for t,cnt in token_counts[:5]:
    resolves=False
    title=''
    # search ticket_root for dirs starting with token
    for d in os.listdir(ticket_root):
        if d.lower().startswith(t.lower()):
            resolves=True
            # read ticket toml if present
            td=os.path.join(ticket_root,d)
            for fn in os.listdir(td):
                if fn.endswith('.toml'):
                    try:
                        with open(os.path.join(td,fn),'r',encoding='utf-8') as f:
                            for line in f:
                                if line.strip().startswith('title'):
                                    # naive parse
                                    parts=line.split('=',1)
                                    if len(parts)>1:
                                        title=parts[1].strip().strip(' \"')
                                        break
                    except Exception:
                        pass
            break
    resolutions.append({'token':t,'count':cnt,'resolves':resolves,'title':title})
out={'sessions_scanned':sessions_scanned,'sessions_with_hex8_token':sessions_with_hex8,'top_tokens':[(t,c) for t,c in top_tokens],'top5_resolutions':resolutions,'sessions_with_target_tickets':len(sessions_with_target),'distinct_target_ids':list(distinct_target_ids)}
print(json.dumps(out,indent=2))
