python3 - << 'PY'
import os, json, uuid, re
from collections import defaultdict
sessions_root = r"c:/Users/linus/git/context-engine/.session/sessions"
ticket_root = r"c:/Users/linus/git/context-engine/.ticket/tickets"

def is_uuid(s):
    try:
        uuid.UUID(s)
        return True
    except Exception:
        return False

def find_ticket_fullid(prefix):
    # if full uuid and exists
    if is_uuid(prefix):
        path = os.path.join(ticket_root, prefix)
        if os.path.isdir(path):
            return prefix
        return None
    # prefix 8 hex
    if re.fullmatch(r'[0-9a-fA-F]{8}', prefix):
        matches = []
        for name in os.listdir(ticket_root):
            if name.lower().startswith(prefix.lower()):
                matches.append(name)
        if len(matches)==1:
            return matches[0]
        return None
    return None


def collect_from_payload(payload, fallback_tool_name=None):
    ids=set()
    if isinstance(payload, list):
        for p in payload:
            ids |= collect_from_payload(p, fallback_tool_name)
        return ids
    if isinstance(payload, dict):
        name = payload.get('name') or fallback_tool_name
        if not name:
            return set()
        name_l = name.lower()
        if ('ticket' not in name_l) and ('board' not in name_l):
            return set()
        arguments = payload.get('arguments') or payload
        if not isinstance(arguments, dict):
            return set()
        for key in ['id','ticket_id','from','to','root']:
            v = arguments.get(key)
            if isinstance(v,str):
                if is_uuid(v) or (len(v)==8 and all(c in '0123456789abcdefABCDEF' for c in v)):
                    ids.add(v.lower())
    return ids

session_count=0
sessions_with_change=0
ticket_to_sessions=defaultdict(set)
skipped_corrupt=0
for sid in os.listdir(sessions_root):
    sdir = os.path.join(sessions_root, sid)
    if not os.path.isdir(sdir):
        continue
    session_count +=1
    try:
        with open(os.path.join(sdir,'session.json'),'r',encoding='utf-8') as f:
            sess = json.load(f)
    except Exception:
        skipped_corrupt+=1
        continue
    metadata = sess.get('metadata',{})
    links = sess.get('links',{})
    existing_ticket_ids = set((links.get('ticket_ids') or []))
    if isinstance(existing_ticket_ids, list):
        existing_ticket_ids = set([s.lower() for s in existing_ticket_ids])
    changed=False
    # worktree branch inference: parse metadata.worktree.branch and path
    worktree = metadata.get('worktree') or None
    if worktree and metadata.get('ticket_id') is None:
        branch = worktree.get('branch','')
        path = worktree.get('path','')
        short=None
        m = re.match(r'agent/([0-9a-fA-F]{8})-', branch)
        if m:
            short = m.group(1).lower()
        else:
            # parse path components for .worktrees/<short>-slug
            comps = path.replace('\\','/').split('/')
            for i,c in enumerate(comps):
